import type { ReactNode } from "react";
import { NavLink } from "react-router";

export function AppShell({ children }: { children: ReactNode }) {
  return (
    <div className="app-shell">
      <header className="topbar">
        <NavLink to="/" className="wordmark">
          KisiEngine
        </NavLink>
        <nav aria-label="Primary">
          <NavLink
            to="/"
            end
            className={({ isActive }) => (isActive ? "nav-link nav-link-active" : "nav-link")}
          >
            Workflows
          </NavLink>
        </nav>
      </header>
      {children}
    </div>
  );
}

import { BrowserRouter, Route, Routes } from "react-router";

import { MISSING_DEMO_ACCESS_KEY_MESSAGE, readDemoAccessKey } from "./api/client";
import { AppShell } from "./components/AppShell";
import { WorkflowEditor } from "./pages/WorkflowEditor";
import { WorkflowList } from "./pages/WorkflowList";

export function App() {
  return (
    <BrowserRouter>
      <AppShell>
        {readDemoAccessKey() === undefined ? (
          <main className="page">
            <h1>Workflows</h1>
            <p role="alert">{MISSING_DEMO_ACCESS_KEY_MESSAGE}</p>
          </main>
        ) : (
          <Routes>
            <Route path="/" element={<WorkflowList />} />
            <Route path="/workflows/new" element={<WorkflowEditor />} />
            <Route path="/workflows/:id" element={<WorkflowEditor />} />
          </Routes>
        )}
      </AppShell>
    </BrowserRouter>
  );
}

import Editor from "@monaco-editor/react";

type JsonEditorProps = {
  value: string;
  onChange: (value: string) => void;
};

export function JsonEditor({ value, onChange }: JsonEditorProps) {
  return (
    <Editor
      height="360px"
      language="json"
      theme="vs-dark"
      value={value}
      onChange={(next) => onChange(next ?? "")}
      options={{
        minimap: { enabled: false },
        scrollBeyondLastLine: false,
        wordWrap: "on",
        tabSize: 2,
        ariaLabel: "Workflow steps",
      }}
    />
  );
}

:root {
  color: #e8eefc;
  background: #070b14;
  font-family: system-ui, sans-serif;
  line-height: 1.5;
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(1200px 480px at 10% -10%, rgba(124, 107, 255, 0.16), transparent 55%),
    #070b14;
}

a {
  color: #93c5fd;
  text-decoration: none;
}

a:hover {
  color: #dbeafe;
}

button,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
}

button:focus-visible,
a:focus-visible,
input:focus-visible {
  outline: 2px solid #93c5fd;
  outline-offset: 2px;
}

.app-shell {
  min-height: 100vh;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 28px;
  padding: 16px 28px;
  background: #101624;
  border-bottom: 1px solid #243049;
}

.wordmark {
  color: #f8fafc;
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.wordmark:hover {
  color: #ffffff;
}

.nav-link {
  color: #93a0b8;
  font-size: 0.95rem;
  font-weight: 600;
  padding: 6px 2px;
  border-bottom: 2px solid transparent;
}

.nav-link:hover,
.nav-link-active {
  color: #e8eefc;
  border-bottom-color: #7c6bff;
}

.page {
  max-width: 1080px;
  margin: 0 auto;
  padding: 36px 24px 64px;
}

h1 {
  margin: 0;
  font-size: 1.85rem;
  letter-spacing: -0.03em;
  line-height: 1.2;
}

h2 {
  margin: 0 0 16px;
  font-size: 0.95rem;
  font-weight: 650;
  letter-spacing: 0.01em;
}

.lede {
  margin: 8px 0 0;
  max-width: 40rem;
  color: #93a0b8;
}

.page-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  margin-bottom: 24px;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 10px 16px;
  background: #1a2336;
  color: #e8eefc;
  font-weight: 650;
  text-decoration: none;
}

.button:hover {
  background: #243049;
  color: #ffffff;
}

.button-primary {
  background: #3b82f6;
  color: #ffffff;
}

.button-primary:hover {
  background: #2563eb;
  color: #ffffff;
}

.button-primary:disabled {
  background: #1e3a5f;
  color: #93a0b8;
}

.panel {
  background: #101624;
  border: 1px solid #243049;
  border-radius: 16px;
  padding: 20px;
}

.panel + .panel,
.editor-form .panel {
  margin-top: 16px;
}

.workflow-table {
  width: 100%;
  border-collapse: collapse;
}

.workflow-table th {
  padding: 0 12px 12px;
  color: #93a0b8;
  font-size: 0.78rem;
  font-weight: 650;
  letter-spacing: 0.04em;
  text-align: left;
  text-transform: uppercase;
}

.workflow-table td {
  padding: 14px 12px;
  border-top: 1px solid #243049;
  vertical-align: middle;
}

.workflow-table tbody tr:hover td {
  background: rgba(59, 130, 246, 0.06);
}

.workflow-name {
  font-weight: 650;
}

.status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1px solid #243049;
  border-radius: 999px;
  padding: 4px 10px;
  background: #0c1220;
  color: #e8eefc;
  font-size: 0.85rem;
  font-weight: 650;
}

.status:hover {
  border-color: #3b82f6;
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: #94a3b8;
}

.status-enabled .status-dot {
  background: #34d399;
  box-shadow: 0 0 0 3px rgba(52, 211, 153, 0.16);
}

.url-pill {
  display: inline-block;
  max-width: 280px;
  overflow: hidden;
  padding: 6px 10px;
  border: 1px solid #243049;
  border-radius: 999px;
  background: #0c1220;
  color: #cbd5e1;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.78rem;
  text-overflow: ellipsis;
  white-space: nowrap;
  vertical-align: middle;
}

.workflow-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border: 1px solid #243049;
  border-radius: 10px;
  background: #0c1220;
  color: #cbd5e1;
}

.icon-button:hover {
  border-color: #3b82f6;
  color: #ffffff;
  background: #172033;
}

.icon-button-danger:hover {
  border-color: #f87171;
  color: #fecaca;
  background: #2a1620;
}

.icon-button svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

label {
  display: block;
  margin: 0 0 16px;
  color: #cbd5e1;
  font-weight: 650;
}

input:not([type="checkbox"]) {
  display: block;
  width: 100%;
  margin-top: 8px;
  padding: 10px 12px;
  border: 1px solid #243049;
  border-radius: 10px;
  background: #0c1220;
}

input:not([type="checkbox"]):hover {
  border-color: #3b4d6d;
}

.switch {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  width: fit-content;
  margin-bottom: 20px;
}

.switch input {
  position: absolute;
  width: 44px;
  height: 24px;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}

.switch-track {
  position: relative;
  width: 44px;
  height: 24px;
  border-radius: 999px;
  background: #243049;
  flex: none;
}

.switch-track::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #e8eefc;
  transition: transform 0.15s ease;
}

.switch input:checked + .switch-track {
  background: #3b82f6;
}

.switch input:checked + .switch-track::after {
  transform: translateX(20px);
}

.switch input:focus-visible + .switch-track {
  outline: 2px solid #93c5fd;
  outline-offset: 2px;
}

.trigger-row {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 10px;
}

.trigger-row label {
  flex: 1 1 16rem;
  margin: 0;
}

.method-badge {
  display: inline-flex;
  align-items: center;
  height: 42px;
  padding: 0 12px;
  border-radius: 10px;
  background: rgba(124, 107, 255, 0.18);
  color: #d6ccff;
  font-size: 0.8rem;
  font-weight: 750;
  letter-spacing: 0.04em;
}

.monaco-frame {
  overflow: hidden;
  border: 1px solid #243049;
  border-radius: 12px;
}

[role="alert"] {
  color: #fecaca;
}

.editor-form > button {
  margin-top: 20px;
}

@media (max-width: 760px) {
  .topbar,
  .page {
    padding-left: 16px;
    padding-right: 16px;
  }

  .page-header {
    flex-direction: column;
    align-items: stretch;
  }

  .workflow-table thead {
    display: none;
  }

  .workflow-table,
  .workflow-table tbody,
  .workflow-table tr,
  .workflow-table td {
    display: block;
    width: 100%;
  }

  .workflow-table tr {
    padding: 8px 0 16px;
    border-top: 1px solid #243049;
  }

  .workflow-table td {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    padding: 8px 0;
    border-top: 0;
  }

  .workflow-table td::before {
    content: attr(data-label);
    color: #93a0b8;
    font-size: 0.75rem;
    font-weight: 650;
    letter-spacing: 0.04em;
    text-transform: uppercase;
  }

  .workflow-table tbody tr:hover td {
    background: transparent;
  }

  .url-pill {
    max-width: 58vw;
  }
}

