import type { Workflow } from "@kisi-workflow/shared";
import { useEffect, useState } from "react";
import { Link } from "react-router";

import { deleteWorkflow, formatApiError, listWorkflows, setWorkflowEnabled } from "../api/client";

function CopyIcon() {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true">
      <rect x="9" y="9" width="11" height="11" rx="2" />
      <path d="M5 15V5a2 2 0 0 1 2-2h10" />
    </svg>
  );
}

function EditIcon() {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true">
      <path d="M12 20h9" />
      <path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4Z" />
    </svg>
  );
}

function DeleteIcon() {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true">
      <path d="M4 7h16" />
      <path d="M9 7V5h6v2" />
      <path d="M7 7l1 12h8l1-12" />
    </svg>
  );
}

export function WorkflowList() {
  const [workflows, setWorkflows] = useState<Workflow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | undefined>(undefined);
  const [copyError, setCopyError] = useState<string | undefined>(undefined);
  const [requestId, setRequestId] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(undefined);
    void listWorkflows()
      .then((next) => {
        if (!cancelled) {
          setWorkflows(next);
        }
      })
      .catch((err: unknown) => {
        if (!cancelled) {
          setError(formatApiError(err));
        }
      })
      .finally(() => {
        if (!cancelled) {
          setLoading(false);
        }
      });
    return () => {
      cancelled = true;
    };
  }, [requestId]);

  async function onDelete(workflow: Workflow) {
    const confirmed = window.confirm(`Delete ${workflow.name}? This cannot be undone.`);
    if (!confirmed) {
      return;
    }
    try {
      await deleteWorkflow(workflow.id);
      setWorkflows((current) => current.filter((item) => item.id !== workflow.id));
    } catch (err: unknown) {
      setError(formatApiError(err));
    }
  }

  async function onToggle(workflow: Workflow) {
    try {
      const updated = await setWorkflowEnabled(workflow.id, !workflow.enabled);
      setWorkflows((current) => current.map((item) => (item.id === updated.id ? updated : item)));
    } catch (err: unknown) {
      setError(formatApiError(err));
    }
  }

  async function onCopy(workflow: Workflow) {
    try {
      await navigator.clipboard.writeText(workflow.triggerUrl);
      setCopyError(undefined);
    } catch {
      setCopyError("Could not copy the trigger URL.");
    }
  }

  return (
    <main className="page">
      <header className="page-header">
        <div>
          <h1>Workflows</h1>
          <p className="lede">Create and manage HTTP-triggered workflows.</p>
        </div>
        <Link className="button button-primary" to="/workflows/new">
          Create Workflow
        </Link>
      </header>
      <section className="panel">
        {loading ? <p>Loading workflows...</p> : null}
        {error !== undefined ? (
          <p role="alert">
            {error}{" "}
            <button type="button" onClick={() => setRequestId((value) => value + 1)}>
              Retry
            </button>
          </p>
        ) : null}
        {copyError !== undefined ? <p role="alert">{copyError}</p> : null}
        {!loading && error === undefined && workflows.length === 0 ? <p>No workflows yet</p> : null}
        {!loading && error === undefined && workflows.length > 0 ? (
          <table className="workflow-table">
            <thead>
              <tr>
                <th>Name</th>
                <th>Status</th>
                <th>Trigger URL</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {workflows.map((workflow) => (
                <tr key={workflow.id}>
                  <td data-label="Name">
                    <span className="workflow-name">{workflow.name}</span>
                  </td>
                  <td data-label="Status">
                    <button
                      type="button"
                      className={workflow.enabled ? "status status-enabled" : "status status-disabled"}
                      aria-label={`${workflow.enabled ? "Disable" : "Enable"} ${workflow.name}`}
                      onClick={() => void onToggle(workflow)}
                    >
                      <span className="status-dot" aria-hidden="true" />
                      {workflow.enabled ? "Enabled" : "Disabled"}
                    </button>
                  </td>
                  <td data-label="Trigger URL">
                    <span className="url-pill" title={workflow.triggerUrl}>
                      {workflow.triggerUrl}
                    </span>
                  </td>
                  <td data-label="Actions">
                    <span className="workflow-actions">
                      <button
                        type="button"
                        className="icon-button"
                        aria-label={`Copy trigger URL for ${workflow.name}`}
                        onClick={() => void onCopy(workflow)}
                      >
                        <CopyIcon />
                      </button>
                      <Link
                        className="icon-button"
                        to={`/workflows/${workflow.id}`}
                        aria-label={`Edit ${workflow.name}`}
                      >
                        <EditIcon />
                      </Link>
                      <button
                        type="button"
                        className="icon-button icon-button-danger"
                        aria-label={`Delete ${workflow.name}`}
                        onClick={() => void onDelete(workflow)}
                      >
                        <DeleteIcon />
                      </button>
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : null}
      </section>
    </main>
  );
}

import type { FormEvent } from "react";
import { useEffect, useState } from "react";
import { Link, useNavigate, useParams } from "react-router";

import {
  createWorkflow,
  formatApiError,
  getWorkflow,
  replaceWorkflow,
} from "../api/client";
import { JsonEditor } from "../components/JsonEditor";
import { validateCreateForm, validateReplaceForm } from "../validation";

export function WorkflowEditor() {
  const { id } = useParams();
  const navigate = useNavigate();
  const isNew = id === undefined;

  const [name, setName] = useState("");
  const [enabled, setEnabled] = useState(true);
  const [stepsText, setStepsText] = useState("[]");
  const [triggerUrl, setTriggerUrl] = useState<string | undefined>(undefined);
  const [loading, setLoading] = useState(id !== undefined);
  const [loadError, setLoadError] = useState<string | undefined>(undefined);
  const [saveError, setSaveError] = useState<string | undefined>(undefined);
  const [saving, setSaving] = useState(false);
  const [copyError, setCopyError] = useState<string | undefined>(undefined);

  useEffect(() => {
    if (id === undefined) {
      return;
    }
    let cancelled = false;
    setLoading(true);
    setLoadError(undefined);
    void getWorkflow(id)
      .then((workflow) => {
        if (cancelled) {
          return;
        }
        setName(workflow.name);
        setEnabled(workflow.enabled);
        setStepsText(JSON.stringify(workflow.steps, null, 2));
        setTriggerUrl(workflow.triggerUrl);
        setLoading(false);
      })
      .catch((error: unknown) => {
        if (cancelled) {
          return;
        }
        setLoadError(formatApiError(error));
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [id]);

  const validation = isNew
    ? validateCreateForm({ name, enabled, stepsText })
    : validateReplaceForm({ name, enabled, stepsText });

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (saving) {
      return;
    }
    setSaving(true);
    setSaveError(undefined);
    try {
      if (isNew) {
        const parsed = validateCreateForm({ name, enabled, stepsText });
        if (!parsed.ok) {
          return;
        }
        const created = await createWorkflow(parsed.body);
        await navigate(`/workflows/${created.id}`);
        return;
      }
      if (id === undefined) {
        return;
      }
      const parsed = validateReplaceForm({ name, enabled, stepsText });
      if (!parsed.ok) {
        return;
      }
      await replaceWorkflow(id, parsed.body);
    } catch (error: unknown) {
      setSaveError(formatApiError(error));
    } finally {
      setSaving(false);
    }
  }

  async function onCopy() {
    if (triggerUrl === undefined) {
      return;
    }
    try {
      await navigator.clipboard.writeText(triggerUrl);
      setCopyError(undefined);
    } catch {
      setCopyError("Could not copy the trigger URL.");
    }
  }

  return (
    <main className="page">
      <header className="page-header">
        <div>
          <h1>{isNew ? "Create workflow" : "Edit workflow"}</h1>
          <p className="lede">
            {isNew
              ? "Define the steps for a new HTTP-triggered workflow."
              : "Update this workflow and its HTTP trigger."}
          </p>
        </div>
      </header>
      {loading ? <p>Loading workflow...</p> : null}
      {loadError !== undefined ? (
        <p role="alert">
          {loadError} <Link to="/">Back to workflows</Link>
        </p>
      ) : null}
      {!loading && loadError === undefined ? (
        <form className="editor-form" onSubmit={(event) => void onSubmit(event)}>
          <label>
            Name
            <input value={name} onChange={(event) => setName(event.target.value)} />
          </label>
          {!validation.ok && validation.errors.name !== undefined ? (
            <p role="alert">{validation.errors.name}</p>
          ) : null}
          <label className="switch">
            <input
              type="checkbox"
              checked={enabled}
              onChange={(event) => setEnabled(event.target.checked)}
            />
            <span className="switch-track" aria-hidden="true" />
            Enabled
          </label>
          <section className="panel">
            <h2>HTTP Trigger</h2>
            {isNew ? <p>The trigger URL is assigned when you save.</p> : null}
            {!isNew && triggerUrl !== undefined ? (
              <div className="trigger-row">
                <span className="method-badge">POST</span>
                <label htmlFor="trigger-url">
                  Trigger URL
                  <input id="trigger-url" readOnly value={triggerUrl} />
                </label>
                <button className="button" type="button" onClick={() => void onCopy()}>
                  Copy
                </button>
              </div>
            ) : null}
            {copyError !== undefined ? <p role="alert">{copyError}</p> : null}
          </section>
          <section className="panel">
            <h2>Steps</h2>
            <div className="monaco-frame">
              <JsonEditor value={stepsText} onChange={setStepsText} />
            </div>
            {!validation.ok && validation.errors.steps !== undefined ? (
              <p role="alert">{validation.errors.steps}</p>
